withLabelsCode.web:
// A palavra de cada um dos cinco estados, os dois moldes da conta e o rótulo
// da ação onde ela existe.
//
// Em espera e concluído ficam sem ação de propósito: disparar o trabalho é de
// quem o enfileirou, e sobre um trabalho pronto não há o que fazer aqui. Os
// outros três têm nomes diferentes porque fazem coisas diferentes.
//
// Os DOIS moldes são obrigatórios, e é decisão: ficar sem total é caso real, e
// um molde só deixaria "de " pendurado no fim da frase.
const rotulos = {
  status: {
    idle: 'Em espera',
    running: 'Em andamento',
    stopped: 'Interrompido',
    complete: 'Concluído',
    failed: 'Falhou',
  },
  count: '{done} de {total}',
  countWithoutTotal: '{done} até agora',
  action: {
    running: 'Parar',
    stopped: 'Retomar',
    failed: 'Tentar de novo',
  },
};

extensibilityCode.web:
// O QUE A BARRA MOSTRA sai do vocabulário compartilhado, e não de um teste
// escrito na tela. São três decisões, e a terceira é a que discordaria entre
// implementações.
jobProgressValue('running', { done: 1240, total: 5000 });  // 24   → a fração
jobProgressValue('running', { done: 1240 });              // null → sem estimativa
jobProgressValue('stopped', { done: 1240 });              // 0    → parado, trilha vazia
jobProgressValue('complete');                             // 100  → cheio, sem conta

// Concluído é cheio ainda que ninguém tenha contado as unidades: barra pela
// metade ao lado da palavra é a peça discordando de si.
//
// E o arredondamento é para BAIXO — ao mais próximo, 4.999 de 5.000 daria cem
// por cento, e a barra encheria antes de o trabalho acabar.
jobProgressValue('running', { done: 4999, total: 5000 }); // 99

// TOTAL ZERO É AUSÊNCIA, e não um denominador: dividir por ele devolveria uma
// fração inválida, e a barra desenharia trilha vazia para um trabalho que não
// tem o que fazer.
hasKnownTotal({ done: 0, total: 0 });  // false

customizationCode.web:
.nds-job-progress {
  max-inline-size: 32rem;
}

/* A barra é REFORÇO, e não a pista: a palavra abaixo dela é o que descreve o
   estado. Mexer na barra não muda o que chega a quem ouve — e o traço que
   percorre o trilho já para sozinho sob movimento reduzido, porque a camada de
   token zera a duração. */
.nds-job-progress .nds-progress {
  block-size: var(--spacing-1);
}

